11	/// The most recent subprocess that exited non-zero, as a redacted summary a failing release can print after its error.
12	static LAST_FAILED_COMMAND: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);
13	
14	const FAILED_COMMAND_TAIL_LINES: usize = 20;
15	const FAILED_COMMAND_TAIL_BYTES: usize = 2048;
16	
17	/// `program`'s exit status and the redacted end of its stderr: at most 20 lines and 2 KiB.
18	fn failed_command_summary(program: &str, exit_code: Option<i32>, stderr: &str) -> String {
19	    let redacted = redact_command_stderr(stderr);
20	    let lines: Vec<&str> = redacted.lines().collect();
21	    let tail = lines[lines.len().saturating_sub(FAILED_COMMAND_TAIL_LINES)..].join("\n");
22	    let mut start = tail.len().saturating_sub(FAILED_COMMAND_TAIL_BYTES);
23	    while !tail.is_char_boundary(start) {
24	        start += 1;
25	    }
26	    let status = exit_code.map_or("was terminated".to_string(), |code| format!("exited with {code}"));
27	    format!("`{program}` {status}\n{}", &tail[start..])
28	}
29	
30	fn note_failed_command(program: &str, exit_code: Option<i32>, stderr: &str) {
31	    if exit_code == Some(0) {
32	        return;
33	    }
34	    if let Ok(mut last) = LAST_FAILED_COMMAND.lock() {
35	        *last = Some(failed_command_summary(program, exit_code, stderr));
36	    }
37	}
