121	fn remove_env(command: &mut std::process::Command, names: &[&str]) {
122	    for name in names {
123	        command.env_remove(name);
124	    }
125	}
126	
127	fn is_named_cargo_registry_token(name: &std::ffi::OsStr) -> bool {
128	    const PREFIX: &[u8] = b"CARGO_REGISTRIES_";
129	    const SUFFIX: &[u8] = b"_TOKEN";
130	    name.to_str().is_some_and(|name| {
131	        let bytes = name.as_bytes();
132	        bytes
133	            .get(..PREFIX.len())
134	            .is_some_and(|prefix| prefix.eq_ignore_ascii_case(PREFIX))
135	            && bytes
136	                .get(bytes.len().saturating_sub(SUFFIX.len())..)
137	                .is_some_and(|suffix| suffix.eq_ignore_ascii_case(SUFFIX))
138	    })
139	}
