141	/// Drops named registry tokens from a non-Cargo child, inherited or explicitly set; call after the child's variables.
142	fn remove_unrelated_cargo_registry_tokens(command: &mut std::process::Command, program: &str) {
143	    if tool_name(program) == "cargo" {
144	        return;
145	    }
146	    let names: Vec<std::ffi::OsString> = std::env::vars_os()
147	        .map(|(name, _)| name)
148	        .chain(command.get_envs().map(|(name, _)| name.to_owned()))
149	        .filter(|name| is_named_cargo_registry_token(name))
150	        .collect();
151	    for name in names {
152	        command.env_remove(name);
153	    }
154	}
