156	pub struct CliCommandRunner;
157	
158	impl CommandRunner for CliCommandRunner {
159	    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
160	        let mut command = std::process::Command::new(program);
161	        command.args(args).current_dir(cwd);
162	        remove_env(&mut command, &unrelated_credentials(program));
163	        remove_unrelated_cargo_registry_tokens(&mut command, program);
164	        let output = command
165	            .stdin(Stdio::null())
166	            .stdout(Stdio::piped())
167	            .stderr(Stdio::piped())
168	            .output();
169	
170	        match output {
171	            Ok(o) => {
172	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
173	                // Keep raw stderr available to callers for protocol/error
174	                // classification, but never leak credentials to the terminal.
175	                if !stderr.is_empty() {
176	                    let secrets = known_credential_env_values(std::env::vars());
177	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
178	                }
179	                note_failed_command(program, o.status.code(), &stderr);
180	                Ok(CommandOutput {
181	                    exit_code: o.status.code(),
182	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
183	                    stderr,
184	                })
185	            }
186	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(CommandError::NotFound {
187	                program: program.to_string(),
188	            }),
189	            Err(e) => Err(CommandError::Io {
190	                program: program.to_string(),
191	                message: e.to_string(),
192	            }),
193	        }
194	    }
195	
196	    fn run_with_timeout(
197	        &self,
198	        program: &str,
199	        args: &[&str],
200	        cwd: &Path,
201	        timeout: Duration,
202	    ) -> Result<CommandOutput, CommandError> {
203	        // `known_credential_env_values` is scanned here, at the trait-method
204	        // call site, rather than inside `run_with_timeout_impl` itself: this
205	        // keeps the impl fn pure and directly unit-testable with a synthetic
206	        // secrets list (no process-env mutation, which would race against
207	        // other tests running in parallel in this binary).
208	        let remove = unrelated_credentials(program);
209	        run_with_timeout_impl(
210	            program,
211	            args,
212	            cwd,
213	            timeout,
214	            LiveEcho::STDERR,
215	            known_credential_env_values(std::env::vars()),
216	            ChildEnvironment {
217	                remove: &remove,
218	                set: &[],
219	            },
220	        )
221	    }
222	
