224	        &self,
225	        program: &str,
226	        args: &[&str],
227	        cwd: &Path,
228	        timeout: Duration,
229	        removed: &[&str],
230	    ) -> Result<CommandOutput, CommandError> {
231	        let remove = unrelated_credentials(program)
232	            .into_iter()
233	            .chain(removed.iter().copied())
234	            .collect::<Vec<_>>();
235	        run_with_timeout_impl(
236	            program,
237	            args,
238	            cwd,
239	            timeout,
240	            LiveEcho::STDERR,
241	            known_credential_env_values(std::env::vars()),
242	            ChildEnvironment {
243	                remove: &remove,
244	                set: &[],
245	            },
246	        )
247	    }
