276	        &self,
277	        program: &str,
278	        args: &[&str],
279	        cwd: &Path,
280	        timeout: Duration,
281	    ) -> Result<CommandOutput, CommandError> {
282	        // Quiet mode never echoes stderr live (see `LiveEcho::NONE`
283	        // below), so there's nothing to redact -- pass an empty secrets
284	        // list rather than paying for an env scan that can only go unused.
285	        let remove = unrelated_credentials(program);
286	        run_with_timeout_impl(
