300	    fn run_with_stdin(
301	        &self,
302	        program: &str,
303	        args: &[&str],
304	        cwd: &Path,
305	        stdin: &[u8],
306	    ) -> Result<CommandOutput, CommandError> {
307	        let mut command = std::process::Command::new(program);
308	        command.args(args).current_dir(cwd);
309	        remove_env(&mut command, &unrelated_credentials(program));
310	        remove_unrelated_cargo_registry_tokens(&mut command, program);
311	        let mut child = command
312	            .stdin(Stdio::piped())
313	            .stdout(Stdio::piped())
314	            .stderr(Stdio::piped())
315	            .spawn()
316	            .map_err(|e| {
317	                if e.kind() == std::io::ErrorKind::NotFound {
318	                    CommandError::NotFound {
319	                        program: program.to_string(),
320	                    }
321	                } else {
322	                    CommandError::Io {
323	                        program: program.to_string(),
324	                        message: e.to_string(),
325	                    }
326	                }
327	            })?;
328	
329	        // Write the payload on its own thread, concurrently with this
330	        // thread draining stdout/stderr via `wait_with_output` below.
331	        // A protocol like `git cat-file --batch` replies to each stdin
332	        // line as it arrives, so writing everything up front on the same
333	        // thread that also has to read the reply back could deadlock once
334	        // either the stdin or the stdout pipe buffer fills -- exactly the
335	        // hazard `run_with_timeout_impl` above uses dedicated reader
336	        // threads to avoid, mirrored here for the write side.
337	        let mut stdin_pipe = child.stdin.take().expect("stdin was requested as piped");
338	        let payload = stdin.to_vec();
339	        let writer = std::thread::spawn(move || {
340	            // A closed read end (the child exited early, e.g. on a bad
341	            // invocation) would otherwise surface as a `BrokenPipe` write
342	            // error here; the child's actual exit code/stderr, captured by
343	            // `wait_with_output` below, is the caller-facing signal for
344	            // that failure, so a write error on this thread is dropped
345	            // rather than reported.
346	            drop(stdin_pipe.write_all(&payload));
347	            drop(stdin_pipe.flush());
348	        });
349	
350	        let output = child.wait_with_output();
351	        // The writer thread only writes then drops its handle, so it must
352	        // already be finished (or about to finish) by the time the child
353	        // has exited and `wait_with_output` has drained its output --
354	        // joining here can't block indefinitely.
355	        drop(writer.join());
356	
357	        match output {
358	            Ok(o) => {
359	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
360	                if !stderr.is_empty() {
361	                    let secrets = known_credential_env_values(std::env::vars());
362	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
363	                }
364	                note_failed_command(program, o.status.code(), &stderr);
365	                Ok(CommandOutput {
366	                    exit_code: o.status.code(),
367	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
368	                    stderr,
369	                })
370	            }
371	            Err(e) => Err(CommandError::Io {
372	                program: program.to_string(),
373	                message: e.to_string(),
374	            }),
375	        }
376	    }
377	}
