379	/// Which of a subprocess's streams [`run_with_timeout_impl`] prints live, to this process's stderr, as lines arrive.
380	/// Captured `CommandOutput` is identical either way; this only affects what the terminal shows while it runs.
381	#[derive(Clone, Copy, PartialEq, Eq)]
382	struct LiveEcho {
383	    stdout: bool,
384	    stderr: bool,
385	}
386	
387	impl LiveEcho {
388	    const NONE: Self = Self {
389	        stdout: false,
390	        stderr: false,
391	    };
392	    const STDERR: Self = Self {
393	        stdout: false,
394	        stderr: true,
395	    };
396	    /// A publish: pnpm prints its errors to stdout, so both streams are shown.
397	    const BOTH: Self = Self {
398	        stdout: true,
399	        stderr: true,
400	    };
401	}
