use std::io::{Read, Write};
use std::path::Path;
use std::process::Stdio;
use std::time::{Duration, Instant};

use callisto_model::{
    known_credential_env_values, redact_command_stderr, redact_known_secrets, CommandError, CommandOutput,
    CommandRunner,
};

/// The most recent subprocess that exited non-zero, as a redacted summary a failing release can print after its error.
static LAST_FAILED_COMMAND: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);

const FAILED_COMMAND_TAIL_LINES: usize = 20;
const FAILED_COMMAND_TAIL_BYTES: usize = 2048;

/// `program`'s exit status and the redacted end of its stderr: at most 20 lines and 2 KiB.
fn failed_command_summary(program: &str, exit_code: Option<i32>, stderr: &str) -> String {
    let redacted = redact_command_stderr(stderr);
    let lines: Vec<&str> = redacted.lines().collect();
    let tail = lines[lines.len().saturating_sub(FAILED_COMMAND_TAIL_LINES)..].join("\n");
    let mut start = tail.len().saturating_sub(FAILED_COMMAND_TAIL_BYTES);
    while !tail.is_char_boundary(start) {
        start += 1;
    }
    let status = exit_code.map_or("was terminated".to_string(), |code| format!("exited with {code}"));
    format!("`{program}` {status}\n{}", &tail[start..])
}

fn note_failed_command(program: &str, exit_code: Option<i32>, stderr: &str) {
    if exit_code == Some(0) {
        return;
    }
    if let Ok(mut last) = LAST_FAILED_COMMAND.lock() {
        *last = Some(failed_command_summary(program, exit_code, stderr));
    }
}

/// The summary of the most recent failed subprocess, if any; printed after an indeterminate release error.
pub fn last_failed_command() -> Option<String> {
    LAST_FAILED_COMMAND.lock().ok().and_then(|last| last.clone())
}

/// Caps how much of a subprocess's stdout/stderr this process will retain
/// in memory. The pipe is still drained in full past this point (bytes
/// beyond the cap are read and discarded, never accumulated) so a chatty
/// child can never deadlock waiting on a full OS pipe buffer -- this
/// bounds memory, not duration (`PUBLISH_TIMEOUT_SECS` bounds that
/// separately).
const MAX_CAPTURED_OUTPUT_BYTES: usize = 10 * 1024 * 1024;

const RELEASE_CREDENTIALS: &[&str] = &[
    // The job's OIDC request: only npm needs it, to attach provenance.
    "ACTIONS_ID_TOKEN_REQUEST_TOKEN",
    "ACTIONS_ID_TOKEN_REQUEST_URL",
    "CARGO_REGISTRY_TOKEN",
    "GH_TOKEN",
    "GITHUB_TOKEN",
    "NPM_CONFIG_TOKEN",
    "NPM_TOKEN",
    "NODE_AUTH_TOKEN",
    "PYPI_TOKEN",
    "CALLISTO_PUBLISH_NPM_CONFIG",
    "TWINE_USERNAME",
    "TWINE_PASSWORD",
];

const ACTION_SECRET_INPUTS: &[&str] = &[
    "CARGO_REGISTRY_TOKEN",
    "GH_TOKEN",
    "GITHUB_TOKEN",
    "NPM_TOKEN",
    "PYPI_TOKEN",
    "CALLISTO_PUBLISH_NPM_CONFIG",
    "TWINE_USERNAME",
    "TWINE_PASSWORD",
];

struct ChildEnvironment<'a> {
    remove: &'a [&'a str],
    set: &'a [(&'a str, &'a str)],
}

/// The release credentials a tool reads from its own environment. Every other release
/// credential is removed from its child process, so a tool never sees a secret it does not use.
/// A tool absent here needs none; publishers receive theirs explicitly instead.
fn credentials_needed_by(tool: &str) -> &'static [&'static str] {
    match tool {
        "npm" | "pnpm" | "yarn" | "bun" => &[
            "NPM_CONFIG_TOKEN",
            "NPM_TOKEN",
            "NODE_AUTH_TOKEN",
            "ACTIONS_ID_TOKEN_REQUEST_TOKEN",
            "ACTIONS_ID_TOKEN_REQUEST_URL",
        ],
        "cargo" => &["CARGO_REGISTRY_TOKEN"],
        // `gh` reads GH_TOKEN, and GITHUB_TOKEN when that is unset; it runs the attestation
        // check and every forge call, and refuses to run without a token.
        "gh" => &["GH_TOKEN", "GITHUB_TOKEN"],
        _ => &[],
    }
}

fn unrelated_credentials(program: &str) -> Vec<&'static str> {
    let tool = tool_name(program);
    let keep = credentials_needed_by(tool);
    RELEASE_CREDENTIALS
        .iter()
        .copied()
        .filter(|credential| !keep.contains(credential))
        .collect()
}

fn tool_name(program: &str) -> &str {
    Path::new(program)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(program)
}

fn remove_env(command: &mut std::process::Command, names: &[&str]) {
    for name in names {
        command.env_remove(name);
    }
}

fn is_named_cargo_registry_token(name: &std::ffi::OsStr) -> bool {
    const PREFIX: &[u8] = b"CARGO_REGISTRIES_";
    const SUFFIX: &[u8] = b"_TOKEN";
    name.to_str().is_some_and(|name| {
        let bytes = name.as_bytes();
        bytes
            .get(..PREFIX.len())
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case(PREFIX))
            && bytes
                .get(bytes.len().saturating_sub(SUFFIX.len())..)
                .is_some_and(|suffix| suffix.eq_ignore_ascii_case(SUFFIX))
    })
}

/// Drops named registry tokens from a non-Cargo child, inherited or explicitly set; call after the child's variables.
fn remove_unrelated_cargo_registry_tokens(command: &mut std::process::Command, program: &str) {
    if tool_name(program) == "cargo" {
        return;
    }
    let names: Vec<std::ffi::OsString> = std::env::vars_os()
        .map(|(name, _)| name)
        .chain(command.get_envs().map(|(name, _)| name.to_owned()))
        .filter(|name| is_named_cargo_registry_token(name))
        .collect();
    for name in names {
        command.env_remove(name);
    }
}

pub struct CliCommandRunner;

impl CommandRunner for CliCommandRunner {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
        let mut command = std::process::Command::new(program);
        command.args(args).current_dir(cwd);
        remove_env(&mut command, &unrelated_credentials(program));
        remove_unrelated_cargo_registry_tokens(&mut command, program);
        let output = command
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .output();

        match output {
            Ok(o) => {
                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
                // Keep raw stderr available to callers for protocol/error
                // classification, but never leak credentials to the terminal.
                if !stderr.is_empty() {
                    let secrets = known_credential_env_values(std::env::vars());
                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
                }
                note_failed_command(program, o.status.code(), &stderr);
                Ok(CommandOutput {
                    exit_code: o.status.code(),
                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
                    stderr,
                })
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(CommandError::NotFound {
                program: program.to_string(),
            }),
            Err(e) => Err(CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            }),
        }
    }

    fn run_with_timeout(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        // `known_credential_env_values` is scanned here, at the trait-method
        // call site, rather than inside `run_with_timeout_impl` itself: this
        // keeps the impl fn pure and directly unit-testable with a synthetic
        // secrets list (no process-env mutation, which would race against
        // other tests running in parallel in this binary).
        let remove = unrelated_credentials(program);
        run_with_timeout_impl(
            program,
            args,
            cwd,
            timeout,
            LiveEcho::STDERR,
            known_credential_env_values(std::env::vars()),
            ChildEnvironment {
                remove: &remove,
                set: &[],
            },
        )
    }

    fn run_with_timeout_env_filtered(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
        removed: &[&str],
    ) -> Result<CommandOutput, CommandError> {
        let remove = unrelated_credentials(program)
            .into_iter()
            .chain(removed.iter().copied())
            .collect::<Vec<_>>();
        run_with_timeout_impl(
            program,
            args,
            cwd,
            timeout,
            LiveEcho::STDERR,
            known_credential_env_values(std::env::vars()),
            ChildEnvironment {
                remove: &remove,
                set: &[],
            },
        )
    }

    fn run_with_timeout_publisher(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
        env: &[(&str, &str)],
    ) -> Result<CommandOutput, CommandError> {
        let remove = unrelated_credentials(program)
            .into_iter()
            .chain(ACTION_SECRET_INPUTS.iter().copied())
            .collect::<Vec<_>>();
        run_with_timeout_impl(
            program,
            args,
            cwd,
            timeout,
            LiveEcho::BOTH,
            known_credential_env_values(std::env::vars()),
            ChildEnvironment {
                remove: &remove,
                set: env,
            },
        )
    }

    fn run_quiet(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        // Quiet mode never echoes stderr live (see `LiveEcho::NONE`
        // below), so there's nothing to redact -- pass an empty secrets
        // list rather than paying for an env scan that can only go unused.
        let remove = unrelated_credentials(program);
        run_with_timeout_impl(
            program,
            args,
            cwd,
            timeout,
            LiveEcho::NONE,
            Vec::new(),
            ChildEnvironment {
                remove: &remove,
                set: &[],
            },
        )
    }

    fn run_with_stdin(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        stdin: &[u8],
    ) -> Result<CommandOutput, CommandError> {
        let mut command = std::process::Command::new(program);
        command.args(args).current_dir(cwd);
        remove_env(&mut command, &unrelated_credentials(program));
        remove_unrelated_cargo_registry_tokens(&mut command, program);
        let mut child = command
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|e| {
                if e.kind() == std::io::ErrorKind::NotFound {
                    CommandError::NotFound {
                        program: program.to_string(),
                    }
                } else {
                    CommandError::Io {
                        program: program.to_string(),
                        message: e.to_string(),
                    }
                }
            })?;

        // Write the payload on its own thread, concurrently with this
        // thread draining stdout/stderr via `wait_with_output` below.
        // A protocol like `git cat-file --batch` replies to each stdin
        // line as it arrives, so writing everything up front on the same
        // thread that also has to read the reply back could deadlock once
        // either the stdin or the stdout pipe buffer fills -- exactly the
        // hazard `run_with_timeout_impl` above uses dedicated reader
        // threads to avoid, mirrored here for the write side.
        let mut stdin_pipe = child.stdin.take().expect("stdin was requested as piped");
        let payload = stdin.to_vec();
        let writer = std::thread::spawn(move || {
            // A closed read end (the child exited early, e.g. on a bad
            // invocation) would otherwise surface as a `BrokenPipe` write
            // error here; the child's actual exit code/stderr, captured by
            // `wait_with_output` below, is the caller-facing signal for
            // that failure, so a write error on this thread is dropped
            // rather than reported.
            drop(stdin_pipe.write_all(&payload));
            drop(stdin_pipe.flush());
        });

        let output = child.wait_with_output();
        // The writer thread only writes then drops its handle, so it must
        // already be finished (or about to finish) by the time the child
        // has exited and `wait_with_output` has drained its output --
        // joining here can't block indefinitely.
        drop(writer.join());

        match output {
            Ok(o) => {
                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
                if !stderr.is_empty() {
                    let secrets = known_credential_env_values(std::env::vars());
                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
                }
                note_failed_command(program, o.status.code(), &stderr);
                Ok(CommandOutput {
                    exit_code: o.status.code(),
                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
                    stderr,
                })
            }
            Err(e) => Err(CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            }),
        }
    }
}

/// Which of a subprocess's streams [`run_with_timeout_impl`] prints live, to this process's stderr, as lines arrive.
/// Captured `CommandOutput` is identical either way; this only affects what the terminal shows while it runs.
#[derive(Clone, Copy, PartialEq, Eq)]
struct LiveEcho {
    stdout: bool,
    stderr: bool,
}

impl LiveEcho {
    const NONE: Self = Self {
        stdout: false,
        stderr: false,
    };
    const STDERR: Self = Self {
        stdout: false,
        stderr: true,
    };
    /// A publish: pnpm prints its errors to stdout, so both streams are shown.
    const BOTH: Self = Self {
        stdout: true,
        stderr: true,
    };
}

/// Drains `reader` to its end and returns what it said, keeping at most [`MAX_CAPTURED_OUTPUT_BYTES`]; the rest is
/// read and dropped so the child never blocks on a full pipe.
///
/// With `echo`, each line is also written to this process's stderr with `secrets` redacted first (registry tools can
/// echo a credential verbatim). The returned text stays raw so classifiers keep matching exact upstream text. Lines
/// are read as bytes: a line iterator has no bound on a single line, so a flood with no newlines would buffer without
/// limit before it could be capped.
fn capture_stream(mut reader: impl Read, echo: bool, secrets: &[String]) -> String {
    let mut captured: Vec<u8> = Vec::new();
    let mut truncated = false;
    let mut pending_line: Vec<u8> = Vec::new();
    let mut chunk = [0u8; 65536];
    let echo_line = |line: &mut Vec<u8>| {
        if line.last() == Some(&b'\r') {
            line.pop();
        }
        eprintln!("{}", redact_known_secrets(&String::from_utf8_lossy(line), secrets));
    };
    loop {
        match reader.read(&mut chunk) {
            Ok(0) | Err(_) => break,
            Ok(n) => {
                let data = &chunk[..n];
                if echo {
                    for &b in data {
                        if b == b'\n' {
                            echo_line(&mut pending_line);
                            pending_line.clear();
                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
                            pending_line.push(b);
                        }
                    }
                }
                if !truncated {
                    let take = data.len().min(MAX_CAPTURED_OUTPUT_BYTES - captured.len());
                    captured.extend_from_slice(&data[..take]);
                    truncated = take < data.len();
                }
            }
        }
    }
    if echo && !pending_line.is_empty() {
        echo_line(&mut pending_line);
    }
    let mut text = String::from_utf8_lossy(&captured).into_owned();
    if truncated {
        text.push_str("\n...[output truncated]\n");
    }
    text
}

/// `live_secrets`: known-credential values (see
/// [`callisto_model::known_credential_env_values`]) to redact from each
/// line *before* it's echoed live to the terminal via `eprintln!`. This is
/// deliberately separate from -- and does not affect -- the `captured`
/// buffer that becomes the returned `CommandOutput.stderr`: that copy must
/// stay byte-for-byte raw so downstream classifiers (e.g.
/// `extract_retry_after_duration`, `detect_auth_failure`) can still match
/// exact upstream text. Callers pass the secrets list in rather than this
/// function reading the environment itself, keeping it pure and testable
/// with a synthetic list.
fn run_with_timeout_impl(
    program: &str,
    args: &[&str],
    cwd: &Path,
    timeout: Duration,
    echo: LiveEcho,
    live_secrets: Vec<String>,
    child_env: ChildEnvironment<'_>,
) -> Result<CommandOutput, CommandError> {
    let mut command = std::process::Command::new(program);
    command
        .args(args)
        .current_dir(cwd)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for name in child_env.remove {
        command.env_remove(name);
    }
    for (name, value) in child_env.set {
        command.env(name, value);
    }
    remove_unrelated_cargo_registry_tokens(&mut command, program);
    let mut child = command.spawn().map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            CommandError::NotFound {
                program: program.to_string(),
            }
        } else {
            CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            }
        }
    })?;

    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
    // when the child produces output while we wait for it to exit.
    let stdout_handle = child.stdout.take().expect("stdout was piped");
    let stderr_handle = child.stderr.take().expect("stderr was piped");

    // The reader threads signal completion over a channel rather than
    // being joined directly. Killing (or the natural exit of) the
    // direct child does NOT close pipe fds held open by a descendant
    // process that inherited them (common for npm/cargo/python publish
    // lifecycle scripts spawning subprocesses). If that happens, the
    // blocking `read()` inside these threads never returns. Using
    // `recv_timeout` below lets us bound how long we wait for them
    // without ever blocking the caller indefinitely.
    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel::<String>();
    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel::<String>();

    let stdout_secrets = live_secrets.clone();
    std::thread::spawn(move || {
        drop(stdout_tx.send(capture_stream(stdout_handle, echo.stdout, &stdout_secrets)));
    });
    // Stderr streams line by line so publish progress (cargo/npm/twine write to stderr) appears in real time rather
    // than after the process exits. `echo` gates only the live printing; captured output is identical either way.
    std::thread::spawn(move || {
        drop(stderr_tx.send(capture_stream(stderr_handle, echo.stderr, &live_secrets)));
    });

    // Grace period to wait for the reader threads after the direct
    // child has exited (or been killed). Bounded so a lingering
    // descendant holding the pipe open can never hang the caller.
    const READER_GRACE: Duration = Duration::from_secs(3);

    let deadline = Instant::now() + timeout;
    let status = loop {
        match child.try_wait().map_err(|e| CommandError::Io {
            program: program.to_string(),
            message: e.to_string(),
        })? {
            Some(s) => break s,
            None => {
                if Instant::now() >= deadline {
                    drop(child.kill());
                    drop(child.wait());
                    // Reader threads are intentionally not joined here:
                    // if a descendant process is still holding a pipe
                    // fd open, join() could block forever. We wait a
                    // bounded grace period for output, then abandon the
                    // threads (they leak until the descendant
                    // eventually exits and closes the fd -- a thread
                    // leak, not a memory-safety issue).
                    let stdout = stdout_rx.recv_timeout(READER_GRACE).ok();
                    let stderr = stderr_rx.recv_timeout(READER_GRACE).ok();
                    if stdout.is_none() || stderr.is_none() {
                        eprintln!(
                            "warning: `{program}` timed out and a descendant process \
                                 appears to still hold its output pipes open; captured \
                                 output may be incomplete"
                        );
                    }
                    return Err(CommandError::TimedOut {
                        program: program.to_string(),
                        seconds: timeout.as_secs(),
                    });
                }
                std::thread::sleep(Duration::from_millis(50));
            }
        }
    };

    // The direct child has exited on its own. Even so, a descendant
    // process can still hold the pipe fds open (e.g. a backgrounded
    // job spawned by a shell script), so bound the wait here too.
    let stdout_result = stdout_rx.recv_timeout(READER_GRACE);
    let stderr_result = stderr_rx.recv_timeout(READER_GRACE);
    // Incomplete output with a clean exit would read as an empty success to every classifier.
    let (Ok(stdout), Ok(stderr)) = (stdout_result, stderr_result) else {
        return Err(CommandError::Io {
            program: program.to_string(),
            message:
                "it exited but a descendant process still holds its output pipes open, so its output is incomplete"
                    .to_string(),
        });
    };

    note_failed_command(program, status.code(), &stderr);
    Ok(CommandOutput {
        exit_code: status.code(),
        stdout,
        stderr,
    })
}

