200	/// Validates git version against the [`REQUIRED_GIT`] floor.
201	///
202	/// `reported` is raw `git --version` output (e.g. `"git version 2.39.5"`,
203	/// `"...2.39.5.windows.1"` on Windows, `"...2.39.5-rc1"` for a pre-release).
204	/// Only the leading `major.minor.patch` triple is parsed, each component
205	/// truncated at its first non-digit char (`5-rc1` -> `5`) before reaching
206	/// `semver`: an unstripped hyphenated suffix would make `semver::VersionReq`
207	/// exclude it from the `>=2.20` floor entirely, since semver reqs never
208	/// match a pre-release unless the requirement itself carries a matching
209	/// tag -- irrelevant to a real git build tag. Extra dot-separated
210	/// components (`.windows.1`) are ignored; a missing minor/patch defaults
211	/// to `0`.
212	///
213	/// Comparison itself is delegated to [`semver::VersionReq`] parsing
214	/// [`REQUIRED_GIT`], so the floor lives in one place, not a hand-maintained
215	/// duplicate that could drift from the error message's constant.
216	pub fn check_git_version(reported: &str) -> Result<(), CommandError> {
217	    let incompatible = || CommandError::IncompatibleVersion {
218	        program: "git".to_string(),
219	        found: reported.to_string(),
220	        required: REQUIRED_GIT.to_string(),
221	    };
222	
223	    let version_str = reported.trim();
224	    let digits = version_str
225	        .split_whitespace()
226	        .find(|word| word.chars().next().is_some_and(|c| c.is_ascii_digit()))
227	        .unwrap_or(version_str);
228	
229	    let mut parts = digits.splitn(4, '.').take(3);
230	    let major = leading_digits(parts.next().unwrap_or("0"));
231	    let minor = leading_digits(parts.next().unwrap_or("0"));
232	    let patch = leading_digits(parts.next().unwrap_or("0"));
233	    let core = format!("{major}.{minor}.{patch}");
234	
235	    let version = semver::Version::parse(&core).map_err(|_parse_err| incompatible())?;
236	    let required = semver::VersionReq::parse(REQUIRED_GIT).map_err(|_parse_err| incompatible())?;
237	
238	    if required.matches(&version) {
239	        Ok(())
240	    } else {
241	        Err(incompatible())
242	    }
243	}
