287	/// Strips a URL's userinfo (`user:pass@` between `scheme://` and the
288	/// host) from every `scheme://...` occurrence in `text`, replacing it
289	/// with `[REDACTED]@`. Token-by-token: within the span from `scheme://`
290	/// to the next whitespace/quote/`<`/`>`, everything up to the *last* `@`
291	/// is treated as userinfo.
292	///
293	/// Deliberately conservative, not strictly RFC 3986-aware: userinfo with
294	/// a raw `/` or a second `@` (an unescaped base64-ish token) is realistic
295	/// in free-form CLI stderr, and using the *first* `@` would under-redact
296	/// exactly that case. Cost: a rare false positive (an `@` that's really
297	/// part of a path, e.g. an npm scoped package in
298	/// `registry.npmjs.org/@myorg/pkg`, gets redacted too) -- acceptable,
299	/// since over-redaction only costs log noise while under-redaction leaks
300	/// a credential.
301	fn redact_url_userinfo(text: &str) -> String {
302	    let mut result = String::with_capacity(text.len());
303	    let mut rest = text;
304	    while let Some(scheme_pos) = rest.find("://") {
305	        let split_at = scheme_pos + 3;
306	        result.push_str(&rest[..split_at]);
307	        let after = &rest[split_at..];
308	        let stop = after
309	            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
310	            .unwrap_or(after.len());
311	        let candidate = &after[..stop];
312	        if let Some(at_pos) = candidate.rfind('@') {
313	            result.push_str("[REDACTED]@");
314	            rest = &after[at_pos + 1..];
315	            continue;
316	        }
317	        rest = after;
318	    }
319	    result.push_str(rest);
320	    result
321	}
