50	    /// Run a publisher with credentials supplied only to that child.
51	    /// Runners without an explicit child-environment implementation fail closed.
52	    fn run_with_timeout_publisher(
53	        &self,
54	        program: &str,
55	        args: &[&str],
56	        cwd: &Path,
57	        timeout: Duration,
58	        env: &[(&str, &str)],
59	    ) -> Result<CommandOutput, CommandError> {
60	        if env.is_empty() {
61	            return self.run_with_timeout(program, args, cwd, timeout);
62	        }
63	        Err(CommandError::Unsupported {
64	            program: program.to_string(),
65	            reason: "this command runner does not support a publisher child environment".to_string(),
66	        })
67	    }
