69	    /// Like [`Self::run_with_timeout`], but for an internal existence/probe
70	    /// check whose stderr looks like a failure on the common path (e.g.
71	    /// `npm view` against an unpublished package prints a 404-shaped "not
72	    /// found" to stderr normally) -- unlike a real, user-facing mutating
73	    /// command, this must not stream that noise live to the terminal, only
74	    /// capture it into [`CommandOutput`] for the caller to classify.
75	    ///
76	    /// Default implementation just delegates to [`Self::run_with_timeout`]
77	    /// (streams live); implementors doing their own live-streaming should
78	    /// override this to suppress it for probe calls.
79	    fn run_quiet(
80	        &self,
81	        program: &str,
82	        args: &[&str],
83	        cwd: &Path,
84	        timeout: Duration,
85	    ) -> Result<CommandOutput, CommandError> {
86	        self.run_with_timeout(program, args, cwd, timeout)
87	    }
88	
89	    /// Like [`Self::run`], but pipes `stdin` to the child process before
90	    /// reading its output. Needed for subcommands with a line-oriented
91	    /// input protocol -- e.g. `git cat-file --batch`, which reads one
92	    /// object identifier per line from stdin and streams each object's
93	    /// contents back on stdout, letting many objects be fetched in one
94	    /// subprocess round trip instead of one invocation per object.
95	    ///
96	    /// The default implementation returns [`CommandError::Unsupported`]:
97	    /// the great majority of [`CommandRunner`] implementors in this
98	    /// workspace (test doubles, etc.) never pipe
99	    /// stdin to a child process, so they don't need to implement this --
100	    /// only a real subprocess-backed runner used for such a call should
101	    /// override it.
102	    fn run_with_stdin(
103	        &self,
104	        program: &str,
105	        _args: &[&str],
106	        _cwd: &Path,
107	        _stdin: &[u8],
108	    ) -> Result<CommandOutput, CommandError> {
109	        Err(CommandError::Unsupported {
110	            program: program.to_string(),
111	            reason: "this CommandRunner does not support piping input to the child process".to_string(),
112	        })
113	    }
114	}
