189	/// Returns the leading run of ASCII digits in `s`, stopping at the first
190	/// non-digit character (or the end of the string). Used to strip anything
191	/// `semver` would otherwise interpret as pre-release/build metadata (a
192	/// hyphen or plus) or a non-numeric trailing suffix, since a git version's
193	/// own reported string was never intended to carry semver's meaning for
194	/// those -- see [`check_git_version`]'s doc comment.
195	fn leading_digits(s: &str) -> &str {
196	    let end = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());
197	    &s[..end]
198	}
