301	    /// though both currently produce the same IncompatibleVersion error.
302	    #[test]
303	    fn rejects_unparseable_version_string() {
304	        assert!(check_git_version("git version unknown").is_err());
305	        assert!(check_git_version("").is_err());
306	    }
