308	    /// A leaking authenticated remote URL in a subprocess's stderr (the
309	    /// realistic GitHub Actions shape: `REDACTED`)
310	    /// must not survive `CommandOutput::redacted_stderr` -- this is the
311	    /// single shared implementation every crate-level `redact_*_stderr`
312	    /// call site now delegates to instead of reimplementing.
313	    #[test]
314	    fn redacted_stderr_strips_authenticated_remote_url_userinfo() {
315	        let output = CommandOutput {
316	            exit_code: Some(128),
