4	#[derive(Debug, thiserror::Error, Clone, PartialEq, Eq)]
5	#[non_exhaustive]
6	pub enum RegistryError {
7	    #[error("Rate limited. Retry after {0:?}")]
8	    RateLimited(Duration),
9	    #[error("Authentication failed: {0}")]
10	    AuthFailed(String),
11	    /// Distinct network-layer failure (e.g. DNS resolution, TCP connect
12	    /// timeout) separate from a registry-level auth or rate-limit response.
13	    /// Reserved for registry implementations that can reliably distinguish
14	    /// network failures from other errors; `SubprocessRegistryClient` currently
15	    /// maps all unrecognised subprocess failures to `Other`.
16	    #[error("Network error: {0}")]
17	    Network(String),
18	    #[error("Other registry error: {0}")]
19	    Other(String),
20	}
