24	    /// machine-readable discriminator in JSON output. Matches the `errorKind`
25	    /// field on `PublishAttemptResult::Failed`.
26	    pub fn kind_str(&self) -> &'static str {
27	        match self {
28	            RegistryError::RateLimited(_) => "rateLimited",
29	            RegistryError::AuthFailed(_) => "authFailed",
30	            RegistryError::Network(_) => "network",
31	            RegistryError::Other(_) => "other",
32	        }
33	    }
