36	/// Outcome of a [`RegistryClient::publish`] call that did not error.
37	///
38	/// Ecosystem CLI publishers (`cargo publish`, `npm publish`, `twine upload`)
39	/// commonly treat "this version is already on the index" as their own
40	/// success/idempotent case rather than a distinct pre-check result. Surfacing
41	/// that here lets `publish` itself be the source of truth for "already
42	/// published", instead of requiring every ecosystem to implement a reliable
43	/// CLI-only [`RegistryClient::is_published`] pre-check (some ecosystems have
44	/// none without reaching for the registry's HTTP API, which this design
45	/// deliberately avoids).
46	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
47	pub enum PublishOutcome {
48	    /// The package/version was newly uploaded to the registry by this call.
49	    Published,
50	    /// The package/version was already present on the registry; this call
51	    /// took no publishing action.
52	    AlreadyPublished,
53	}
54	
55	pub trait RegistryClient: Send + Sync {
56	    /// Best-effort, optional pre-check for whether `package@version` is
57	    /// already on the registry. Implementations may always return `Ok(false)`
58	    /// when no reliable CLI-only check exists for their ecosystem — in that
59	    /// case `publish`'s own [`PublishOutcome::AlreadyPublished`]
60	    /// classification is the real source of truth, and callers must not
61	    /// treat `Ok(false)` here as a guarantee the package is unpublished.
62	    fn is_published(&self, package: &PackageId, version: &Version) -> Result<bool, RegistryError>;
63	
64	    /// Publishes `package@version`, or reports that it was already published
65	    /// as a non-error, non-action outcome.
66	    ///
67	    /// The highest-stakes side effect in the codebase -- an upload to a public
68	    /// registry is not revertible -- so it requires an [`ApplyPermit`]. A dry
69	    /// run cannot obtain one and therefore cannot reach this method.
70	    /// [`Self::is_published`] is read-only and needs no permit.
71	    fn publish(
72	        &self,
73	        package: &PackageId,
74	        version: &Version,
75	        permit: &ApplyPermit,
76	    ) -> Result<PublishOutcome, RegistryError>;
77	}
