79	/// Gate on whether a publish retry should proceed after a registry reports
80	/// [`RegistryError::RateLimited`]. Called with the registry-supplied `retry_after` duration
81	/// immediately before the caller would sleep and retry; returning `Err` aborts the retry
82	/// instead (the `?`-propagated error becomes the publish attempt's final failure). The
83	/// production implementation (`AlwaysRetryPolicy`, `callisto-graph`) always permits the
84	/// retry — the caller's own overall wait-time cutoff is what bounds retries, not this trait —
85	/// but the seam exists so a caller with a stricter policy (or a test asserting retry
86	/// behavior without real waiting) can substitute one without touching the retry loop itself.
87	pub trait RateLimitPolicy: Send + Sync {
88	    fn check_rate_limit(&self, retry_after: Duration) -> Result<(), RegistryError>;
89	}
