91	/// Injectable clock and sleep seam for publish-retry backoff, so retry logic is testable
92	/// without a real wall-clock wait. The production implementation (`SystemTimeProvider`,
93	/// `callisto-graph`) wraps `std::time::SystemTime::now()`/`std::thread::sleep`; a test
94	/// double can record calls and return instantly instead.
95	pub trait TimeProvider: Send + Sync {
96	    fn now(&self) -> std::time::SystemTime;
97	    fn sleep(&self, duration: Duration);
98	}
