100	/// Redacts every occurrence of any non-empty string in `secrets` from
101	/// `text`, replacing each with `[REDACTED]`, then strips any URL userinfo
102	/// component (`REDACTED` -> `scheme://host`) regardless of
103	/// whether it matched a known secret.
104	///
105	/// Callers use this on raw subprocess stderr before it's embedded in a
106	/// [`RegistryError`] and, downstream, a JSON report or CI log — registry
107	/// CLIs (`cargo publish`, `npm publish`, `twine upload`) can echo a
108	/// credential verbatim in their own error diagnostics on auth failure.
109	///
110	/// Pure and injectable (`secrets` rather than reading the environment
111	/// directly) so it stays deterministic and test-friendly; see
112	/// [`known_credential_env_values`] for the real caller-side source of
113	/// `secrets`.
114	pub fn redact_known_secrets(text: &str, secrets: &[String]) -> String {
115	    let mut redacted = text.to_string();
116	    for secret in secrets {
117	        if !secret.is_empty() {
118	            redacted = redacted.replace(secret.as_str(), "[REDACTED]");
119	        }
120	    }
121	    redact_url_userinfo(&redact_token_shapes(&redacted))
122	}
