124	/// Token prefixes, the shortest run after each that counts as a token, so ordinary words are left alone.
125	const REDACTED_PREFIXES: &[(&str, usize)] = &[
126	    ("npm_", 20),
127	    ("ghp_", 20),
128	    ("gho_", 20),
129	    ("ghu_", 20),
130	    ("ghs_", 20),
131	    ("ghr_", 20),
132	    ("github_pat_", 20),
133	    ("pypi-", 20),
134	];
135	
136	fn is_token_char(c: char) -> bool {
137	    c.is_ascii_alphanumeric() || matches!(c, '_' | '-')
138	}
139	
140	/// Masks credentials that a registry tool echoes although none of them is in a known environment variable: tokens
141	/// with a well-known prefix, `Bearer` values and the value of an `.npmrc` `_authToken`, `_auth` or `_password` line.
142	fn redact_token_shapes(text: &str) -> String {
143	    let mut redacted = text.to_string();
144	    for (prefix, min_len) in REDACTED_PREFIXES {
145	        redacted = mask_after(
146	            &redacted,
147	            prefix,
148	            true,
149	            |value| value.chars().take_while(|c| is_token_char(*c)).count(),
150	            *min_len,
151	        );
152	    }
153	    redacted = mask_bearer(&redacted);
154	    for key in ["_authToken=", "_auth=", "_password="] {
155	        redacted = mask_after(
156	            &redacted,
157	            key,
158	            false,
159	            |value| {
160	                value
161	                    .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
162	                    .unwrap_or(value.len())
163	            },
164	            1,
165	        );
166	    }
167	    redacted
168	}
169	
170	/// Replaces `prefix` plus the value that follows with `[REDACTED]` (a `key=` keeps the key). `value_len` measures the
171	/// value, in bytes of its leading run, and a value shorter than `min_len` characters is not a credential. A `prefix`
172	/// glued to a preceding word is not a token start when `word_boundary` is set, and `${NAME}` placeholders are kept.
173	fn mask_after(
174	    text: &str,
175	    prefix: &str,
176	    word_boundary: bool,
177	    value_len: impl Fn(&str) -> usize,
178	    min_len: usize,
179	) -> String {
180	    let mut result = String::with_capacity(text.len());
181	    let mut rest = text;
182	    while let Some(position) = rest.find(prefix) {
183	        let (before, from_prefix) = rest.split_at(position);
184	        let after_prefix = &from_prefix[prefix.len()..];
185	        let boundary_ok = !word_boundary || before.chars().next_back().is_none_or(|c| !is_token_char(c));
186	        let measured = value_len(after_prefix);
187	        let value = &after_prefix[..measured];
188	        let long_enough = value.chars().count() >= min_len && !value.starts_with("${");
189	        result.push_str(before);
190	        if boundary_ok && long_enough {
191	            if word_boundary {
192	                result.push_str("[REDACTED]");
193	            } else {
194	                result.push_str(prefix);
195	                result.push_str("[REDACTED]");
196	            }
197	            rest = &after_prefix[measured..];
198	        } else {
199	            result.push_str(prefix);
200	            rest = after_prefix;
201	        }
202	    }
203	    result.push_str(rest);
204	    result
205	}
206	
207	/// Masks the credential after `Bearer ` (any case) when it is long enough to be one, so prose such as
208	/// `Bearer authentication failed` is kept.
209	fn mask_bearer(text: &str) -> String {
210	    let lower = text.to_ascii_lowercase();
211	    let mut result = String::with_capacity(text.len());
212	    let mut cursor = 0;
213	    while let Some(found) = lower[cursor..].find("bearer ") {
214	        let start = cursor + found;
215	        let value_start = start + "bearer ".len();
216	        let value_len = text[value_start..]
217	            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
218	            .unwrap_or(text.len() - value_start);
219	        result.push_str(&text[cursor..value_start]);
220	        if value_len >= 16 {
221	            result.push_str("[REDACTED]");
222	            cursor = value_start + value_len;
223	        } else {
224	            cursor = value_start;
225	        }
226	    }
227	    result.push_str(&text[cursor..]);
228	    result
229	}
