231	/// Filters an env-var snapshot down to registry-credential values this
232	/// codebase's publish flow reads: the names in [`SECRET_CREDENTIAL_ENV`], plus any
233	/// `CARGO_REGISTRIES_<NAME>_REDACTED` (operator-configured, unbounded name,
234	/// so matched by pattern). `GITHUB_REDACTED`/`GH_REDACTED` cover GitHub Actions'
235	/// ambient credential -- `redact_url_userinfo` already catches its most
236	/// realistic leak shape (an authenticated remote URL) independently, but
237	/// matching the env var names directly is cheap insurance against other
238	/// leak shapes.
239	///
240	/// Takes the snapshot as a parameter (callers pass `std::env::vars()`)
241	/// rather than reading the environment directly -- deterministic, no
242	/// process-env mutation in tests.
243	pub fn known_credential_env_values(vars: impl Iterator<Item = (String, String)>) -> Vec<String> {
244	    vars.filter(|(key, value)| {
245	        !value.is_empty()
246	            && (SECRET_CREDENTIAL_ENV.contains(&key.as_str())
247	                || (key.starts_with("CARGO_REGISTRIES_") && key.ends_with("_REDACTED"))
248	                || (value.len() >= MIN_SECRET_VALUE_LEN && SECRET_NAME_SUFFIXES.iter().any(|s| key.ends_with(s))))
249	    })
250	    .map(|(_, value)| value)
251	    .collect()
252	}
253	
254	/// Any variable named like a secret has its value redacted too, unless the value is so short that masking it would
255	/// mangle ordinary text.
256	const SECRET_NAME_SUFFIXES: &[&str] = &["_REDACTED", "_SECRET", "_PASSWORD"];
257	const MIN_SECRET_VALUE_LEN: usize = 8;
258	
259	/// The environment variables whose values are secrets. A username and the paths of generated config files
260	/// (`TWINE_USERNAME`, `NPM_CONFIG_USERCONFIG`, `CALLISTO_PUBLISH_NPM_CONFIG`) are credentials to keep out of
261	/// unrelated children but are not secret values, so they are not listed.
262	pub const SECRET_CREDENTIAL_ENV: &[&str] = &[
263	    "ACTIONS_ID_REDACTED_REQUEST_REDACTED",
264	    "NPM_REDACTED",
265	    "NPM_CONFIG_REDACTED",
266	    "NODE_AUTH_REDACTED",
267	    "PYPI_REDACTED",
268	    "TWINE_PASSWORD",
269	    "CARGO_REGISTRY_REDACTED",
270	    "GITHUB_REDACTED",
271	    "GH_REDACTED",
272	];
