274	/// The one definition of "how this workspace redacts a subprocess's stderr":
275	/// [`redact_known_secrets`] over [`known_credential_env_values`] of the live
276	/// environment. Every path that puts child stderr in front of a human -- the
277	/// live echo, [`crate::CommandOutput::redacted_stderr`], and the
278	/// `CommandFailure::NonZeroExit` diagnostic -- composes it here rather than
279	/// repeating the composition, so none of them can drift out of step.
280	///
281	/// Reads the environment, so it is deliberately not the pure primitive;
282	/// unit tests target [`redact_known_secrets`] with an explicit secret list.
283	pub fn redact_command_stderr(stderr: &str) -> String {
284	    redact_known_secrets(stderr, &known_credential_env_values(std::env::vars()))
285	}
